UPDATE habit_executions
SET status = #{newStatus},
    version = #{version} + 1,
    completed_at = CASE WHEN #{newStatus} = 'COMPLETED' THEN #{now} ELSE completed_at END,
    updated_at = #{now}
WHERE id = #{id}
  AND status = #{oldStatus}
  AND version = #{version}

