SELECT *
FROM habit_executions
WHERE habit_id = #{habitId}
  AND status = #{status}
ORDER BY scheduled_at

mapper.update:
UPDATE habit_executions
SET status = 'CANCELLED',
    version = version + 1,
    updated_at = #{now}
WHERE habit_id = #{habitId}
  AND status IN ('SCHEDULED', 'DELIVERED', 'ACKNOWLEDGED')
